(function () {
    'use strict';

    var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* ── Scroll-reveal ── */
    var REVEAL_SELECTORS = [
        '.section-head',
        '.steps-grid article',
        '.article-card',
        '.ann-card',
        '.policy-item',
        '.indexer-card',
        '.indexer-chip',
        '.quick-links a',
        '.trust-links a',
        '.stat-cell',
        '.hero-stat',
        '.posi-stat',
        '.directory-item',
        '.guide-section',
        '.contact-block',
        '.archive-statement',
        '.steps-cta',
        '.indexer-strip-head',
        '.imprints-intro',
        '.imprints-logos',
        '.nx-about',
        '.nx-journal-card',
        '.nx-subject-row',
        '.sb-card'
    ];

    var supportsIO = typeof IntersectionObserver !== 'undefined';

    var revealObs = supportsIO ? new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
            if (!entry.isIntersecting) return;
            entry.target.classList.add('visible');
            revealObs.unobserve(entry.target);
        });
    }, { threshold: 0.1, rootMargin: '0px 0px -32px 0px' }) : null;

    REVEAL_SELECTORS.forEach(function (sel) {
        document.querySelectorAll(sel).forEach(function (el) {
            var parent = el.parentElement;
            if (parent) {
                var siblings = Array.prototype.slice.call(parent.children);
                var idx = siblings.indexOf(el);
                if (idx >= 1 && idx <= 8) el.classList.add('d' + idx);
            }
            if (!supportsIO) {
                // No IntersectionObserver support: show content immediately rather than leaving it invisible.
                el.classList.add('visible');
                return;
            }
            el.classList.add('reveal');
            revealObs.observe(el);
        });
    });

    // Safety net: guarantee every reveal-tracked element becomes visible within a
    // bounded time even if the observer never fires for it (fast/momentum scroll
    // skipping past it, an element left out of the initial DOM pass, screenshot or
    // print tooling that doesn't scroll, etc.) so content and buttons never end up
    // permanently stuck at opacity 0.
    if (supportsIO) {
        setTimeout(function () {
            document.querySelectorAll('.reveal:not(.visible)').forEach(function (el) {
                el.classList.add('visible');
                revealObs.unobserve(el);
            });
        }, 2500);
    }

    /* ── Number counter ──
       Credential numbers (journal counts, POSI coverage figures) count
       up from zero as they enter view instead of just fading in --
       these are the site's core trust signals, so they get the most
       visible motion on the page. Skipped for identifiers with a
       decimal point (the Crossref DOI prefix) since those aren't a
       quantity that "grew"; the comma flag preserves thousands
       separators (POSI's "1,000" reads as 1,000 throughout, not 1000). */
    function parseTarget(text) {
        var clean = text.trim();
        var isPlus = clean.slice(-1) === '+';
        var hasDot = clean.indexOf('.') !== -1 && !isPlus;
        if (hasDot) return null;
        var hasComma = clean.indexOf(',') !== -1;
        var num = parseInt(clean.replace(/[^0-9]/g, ''), 10);
        if (isNaN(num) || num <= 0) return null;
        return { value: num, suffix: isPlus ? '+' : '', comma: hasComma };
    }

    function formatCount(n, comma) {
        return comma ? n.toLocaleString('en-US') : String(n);
    }

    function runCounter(el, target, suffix, comma) {
        if (reduceMotion) { el.textContent = formatCount(target, comma) + suffix; return; }
        var duration = 1100, startTime = null;
        el.textContent = formatCount(0, comma) + suffix;
        function tick(ts) {
            if (!startTime) startTime = ts;
            var p = Math.min((ts - startTime) / duration, 1);
            var eased = 1 - Math.pow(1 - p, 3);
            el.textContent = formatCount(Math.floor(eased * target), comma) + suffix;
            if (p < 1) requestAnimationFrame(tick);
            else el.textContent = formatCount(target, comma) + suffix;
        }
        requestAnimationFrame(tick);
    }

    var counterObs = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
            if (!entry.isIntersecting) return;
            var el = entry.target;
            var parsed = parseTarget(el.textContent);
            if (parsed) runCounter(el, parsed.value, parsed.suffix, parsed.comma);
            counterObs.unobserve(el);
        });
    }, { threshold: 0.6 });

    document.querySelectorAll('.stat-cell strong, .hero-stat strong, .posi-stat strong').forEach(function (el) {
        counterObs.observe(el);
    });

    /* ── Kicker red-line grow on scroll ── */
    var kickerObs = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
            if (!entry.isIntersecting) return;
            entry.target.classList.add('animated');
            kickerObs.unobserve(entry.target);
        });
    }, { threshold: 0.8 });

    document.querySelectorAll('.kicker').forEach(function (el) {
        kickerObs.observe(el);
    });

    /* ── Section-boundary draw-in ──
       A full-width red rule draws across the top of every major section
       the first time it crosses into view -- the kicker's small
       draw-in line, but at page-structural scale, so scrolling through
       the page reads as a sequence of deliberate beats. CSS lives at
       "main section:not(.hero)::before" in institutional.css. */
    var sectionDrawObs = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
            if (!entry.isIntersecting) return;
            entry.target.classList.add('section-draw');
            sectionDrawObs.unobserve(entry.target);
        });
    }, { threshold: 0, rootMargin: '0px 0px -15% 0px' });

    document.querySelectorAll('main section:not(.hero)').forEach(function (el) {
        sectionDrawObs.observe(el);
    });

    /* ── Hero parallax depth ──
       Native CSS scroll-driven animation (animation-timeline: scroll())
       handles this with zero JS cost on browsers that support it -- see
       the @supports (animation-timeline: scroll()) block in
       institutional.css. This is the fallback for browsers that don't:
       a CSS custom property updated via an rAF-throttled scroll
       listener. Skipped entirely when the native path is available, or
       under prefers-reduced-motion. */
    var supportsScrollTimeline = !!(window.CSS && CSS.supports && CSS.supports('animation-timeline: scroll()'));
    var heroSection = document.querySelector('.hero-home');
    if (heroSection && !reduceMotion && !supportsScrollTimeline) {
        var parallaxTicking = false;
        var updateParallax = function () {
            var rect = heroSection.getBoundingClientRect();
            var y = (rect.bottom > 0 && rect.top < window.innerHeight) ? -rect.top : 0;
            document.documentElement.style.setProperty('--parallax-y', y);
            parallaxTicking = false;
        };
        window.addEventListener('scroll', function () {
            if (!parallaxTicking) {
                requestAnimationFrame(updateParallax);
                parallaxTicking = true;
            }
        }, { passive: true });
        updateParallax();
    }

    /* ── Author-guide reading progress (for-authors.html only) ──
       Same native-CSS-first, JS-fallback pattern as the hero parallax
       above: the fill itself is a scroll(root)-driven animation in CSS
       where supported; this listener only exists for browsers without
       that feature. Not gated on prefers-reduced-motion -- it's a 1:1
       reflection of the user's own scroll input (like a scrollbar), not
       autonomous motion, so it isn't the kind of effect that guidance
       asks to suppress. */
    var guideProgress = document.querySelector('.guide-progress');
    if (guideProgress && !supportsScrollTimeline) {
        var progressTicking = false;
        var updateGuideProgress = function () {
            var doc = document.documentElement;
            var scrollable = doc.scrollHeight - doc.clientHeight;
            var pct = scrollable > 0 ? Math.min(Math.max(window.scrollY / scrollable, 0), 1) : 0;
            guideProgress.style.transform = 'scaleX(' + pct + ')';
            progressTicking = false;
        };
        window.addEventListener('scroll', function () {
            if (!progressTicking) {
                requestAnimationFrame(updateGuideProgress);
                progressTicking = true;
            }
        }, { passive: true });
        updateGuideProgress();
    }

})();

