    var WORLD_LAT_MIN = -58, WORLD_LAT_MAX = 76;

    /* real equirectangular projection, true degree scale (no
       stretch-to-fit distortion). Anchored so Europe/Africa/Asia/
       Australia read clearly to the right of the hero text, while the
       Americas fall mostly under the (vignetted) text column — both
       the map dots and the hub markers share this one mapping, so
       hubs land on their real coastline position.

       The scale is derived from W, not H. Hero height is driven by
       how many lines the H1/lead wrap to, which varies a lot by
       language (en ~725px vs zh-cn/ar ~477px at the same 1440px
       viewport) — tying scale to H made the map visibly bigger or
       smaller depending on the active language. W is the same for
       everyone at a given viewport, so the map now renders at one
       consistent size and is simply centered in whatever H it gets. */
    var PX_PER_DEG_FACTOR = 0.0032;
    function project(lat, lon) {
        var pxPerDeg = W * PX_PER_DEG_FACTOR;
        var mapH = pxPerDeg * (WORLD_LAT_MAX - WORLD_LAT_MIN);
        var topY = (H - mapH) / 2;
        var ty = (lat - WORLD_LAT_MIN) / (WORLD_LAT_MAX - WORLD_LAT_MIN);
        var x = W * 0.50 + lon * pxPerDeg;
        /* the hero text column swaps to the right side in RTL layouts
           (see [dir="rtl"] .hero-body in institutional.css) — mirror
           the map so it still sits on the opposite, clear side */
        if (isRTL) x = W - x;
        return [x, topY + (1 - ty) * mapH];
    }

    function buildLandBuffer() {
        landBuffer = document.createElement('canvas');
        landBuffer.width = W; landBuffer.height = H;
        var lc = landBuffer.getContext('2d');
        lc.fillStyle = '#ffffff';
        for (var i = 0; i < LAND_DOTS.length; i++) {
            var p = project(LAND_DOTS[i][0], LAND_DOTS[i][1]);
            if (p[0] < -4 || p[0] > W + 4 || p[1] < -4 || p[1] > H + 4) continue;
            lc.globalAlpha = 0.62;
            lc.beginPath(); lc.arc(p[0], p[1], 1.6, 0, Math.PI * 2); lc.fill();
        }
    }

    function buildArc(a, b) {
        var dx = b.x - a.x, dy = b.y - a.y;
        var mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
        var dist = Math.sqrt(dx * dx + dy * dy);
        var lift = Math.min(dist * 0.28, H * 0.34);
        /* control point lifted "up" (toward smaller y) for a great-circle feel */
        var nx = -dy / (dist || 1), ny = dx / (dist || 1);
        if (ny > 0) { nx = -nx; ny = -ny; }
        return { x0: a.x, y0: a.y, x1: b.x, y1: b.y, cx: mx + nx * lift, cy: my + ny * lift, dist: dist };
    }

